import { fileURLToPath } from 'node:url'
import { drizzle as drizzlePostgres } from 'drizzle-orm/node-postgres'
import { migrate as migratePostgres } from 'drizzle-orm/node-postgres/migrator'
import type { PgliteDatabase } from 'drizzle-orm/pglite'
import { migrate as migratePglite } from 'drizzle-orm/pglite/migrator'
import type pg from 'pg'
import type { DbHandle, Schema } from './client'

/** SQL migrations generated by drizzle-kit, shipped next to the package sources. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations', import.meta.url))

// Arbitrary constant shared by every Mailsink process (boot and `mailsink migrate`).
const MIGRATION_LOCK_KEY = 7_042_026

export interface MigrateOptions {
  /** Override when the migrations are not next to the sources (bundled CLI). */
  migrationsFolder?: string
}

/**
 * Applies pending migrations. Idempotent: already applied migrations are skipped.
 * On Postgres a session advisory lock serializes concurrent callers (boot vs CLI).
 */
export async function migrate(handle: DbHandle, options: MigrateOptions = {}): Promise<void> {
  const config = { migrationsFolder: options.migrationsFolder ?? MIGRATIONS_FOLDER }
  if (handle.driver === 'pglite') {
    await migratePglite(handle.db as PgliteDatabase<Schema>, config)
    return
  }
  const conn = await (handle.client as pg.Pool).connect()
  try {
    await conn.query('select pg_advisory_lock($1)', [MIGRATION_LOCK_KEY])
    await migratePostgres(drizzlePostgres({ client: conn }), config)
  } finally {
    await conn.query('select pg_advisory_unlock($1)', [MIGRATION_LOCK_KEY]).catch(() => {})
    conn.release()
  }
}
